// Actual Studio and CareerProvider; fictional records and local simulated API only.
import {build} from 'esbuild';
import {createServer} from 'node:http';
import {mkdtemp,readFile,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';
const root=fileURLToPath(new URL('../../',import.meta.url)),dir=await mkdtemp(join(tmpdir(),'si-saved-role-'));
await build({stdin:{contents:`import React,{useState,useEffect} from 'react';import {createRoot} from 'react-dom/client';import {CareerProvider,useCareer,emptyData} from './src/career-data';import {CareerTools} from './src/career';import './src/styles.css';
const initial=emptyData(),q=new URLSearchParams(location.search),id='a'.repeat(24);let sourceState=q.get('state')||'held',checks=0,generations=0,unexpected=0;
initial.profile={...initial.profile,name:'Fictional Applicant',cv:'Fictional teacher with a degree. Taught English at a fictional school and prepared classroom lessons. No real applicant or employer.'};
initial.applications=[{id:'fictional-application',jobId:q.has('manual')?'manual-59f8222b-1900-4c36-b562-b21e67eb1f8c':id,title:'Fictional Teacher',company:'Fictional School',location:'Fictional place',description:'Fictional advert: prepare classroom lessons, teach English and communicate clearly with students. This is not a real vacancy.',url:'https://example.test/fictional-role',sponsorship:'not_stated',evidence:'',stage:'Preparing',notes:'PRIVATE FICTIONAL NOTE',cv:'Keep this existing fictional CV draft.',analysis:'Existing fictional evidence notes.',coverLetter:'Keep this existing fictional letter.',checkedAt:'',createdAt:'',updatedAt:'',preparedAt:'',interview:'',portfolio:'',companyResearch:'',learningPlan:'',followUp:''}];
if(q.has('new-manual'))initial.applications=[];
localStorage.setItem('si.career.guest.v2',JSON.stringify({data:initial,revision:0,dirty:false}));
window.fetch=async(url,options)=>{const path=String(url);if(path==='/api/auth/get-session')return Response.json({user:null});if(path.startsWith('/api/career/availability?')){checks++;return sourceState==='unavailable'?Response.json({error:'Fictional unavailable'},{status:503}):Response.json({jobId:id,state:sourceState});}if(path==='/api/career/generate'){generations++;return Response.json({error:'No actual generation is permitted in this browser fixture.'},{status:503});}if(path==='/api/metrics')return new Response(null,{status:204});unexpected++;return Response.json({error:'No external request allowed'},{status:400});};
function View(){const c=useCareer(),[view,go]=useState(q.has('new-manual')?'applications':'studio'),[tick,setTick]=useState(0);useEffect(()=>{const t=setInterval(()=>setTick(x=>x+1),250);return()=>clearInterval(t)},[]);return <main style={{padding:16,maxWidth:1000,margin:'auto'}}><h1>Fictional saved-role QA</h1><p>No production data, real model calls or external providers.</p><p aria-label="QA viewport">Viewport {document.documentElement.clientWidth}px; page width {document.documentElement.scrollWidth}px</p><button onClick={()=>{sourceState='held';setTick(x=>x+1)}}>Hold before next check</button><button onClick={()=>{sourceState='current';setTick(x=>x+1)}}>Make source current</button><p aria-label="QA counters">Status checks: {checks}; generation requests: {generations}; unexpected requests: {unexpected}; source: {sourceState}</p><p aria-label="QA preservation">Source CV unchanged: {String(c.data.profile.cv===initial.profile.cv)}; notes unchanged: {String(!initial.applications.length||c.data.applications[0]?.notes===initial.applications[0].notes)}</p>{['studio','applications'].includes(view)?<CareerTools mode={view} go={go}/>:<p>Navigation reached {view}; no live destination was requested.</p>}</main>}createRoot(document.getElementById('root')).render(<CareerProvider><View/></CareerProvider>);`,loader:'tsx',resolveDir:root},bundle:true,outfile:join(dir,'app.js'),logLevel:'silent'});
const server=createServer(async(req,res)=>{try{const url=new URL(req.url,'http://127.0.0.1:5233');if(url.pathname==='/phone'){res.writeHead(200,{'Content-Type':'text/html'});return res.end('<!doctype html><html><meta name="viewport" content="width=device-width,initial-scale=1"><body style="margin:0"><iframe title="Fictional 390px phone viewport" src="/?state=held" style="display:block;width:390px;height:844px;border:0;margin:auto"></iframe></body></html>');}if(['/app.js','/app.css'].includes(url.pathname)){res.writeHead(200,{'Content-Type':url.pathname.endsWith('.js')?'application/javascript':'text/css'});return res.end(await readFile(join(dir,url.pathname.slice(1))));}res.writeHead(200,{'Content-Type':'text/html'});res.end('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fictional saved-role QA</title><link rel="stylesheet" href="/app.css"><div id="root"></div><script src="/app.js"></script></html>');}catch{res.writeHead(500);res.end('Local fixture failed')}});
server.listen(5233,'127.0.0.1',()=>console.log('Fictional saved-role preview: http://127.0.0.1:5233'));
process.on('SIGINT',async()=>{server.close();await rm(dir,{recursive:true,force:true});process.exit(0)});
